tool_input.command:
python - <<'E'
p='Remap.cs'
s=open(p).read()
s=s.replace('"Remaps a number from a source range to a target range", "Bench", "Math"','"Remaps a number from a source range to a target range", "Bench", "Mapping"')
s=s.replace('AddNumberParameter("Value", "V", "Value to remap"','AddNumberParameter("Number", "N", "Number to remap"')
s=s.replace('''"Target range end", GH_ParamAccess.item);
''','''"Target range end", GH_ParamAccess.item);
            pManager.AddBooleanParameter("Clamp", "C", "Clamp the result to the target range", GH_ParamAccess.item, false);
''')
s=s.replace('''"Remapped value", GH_ParamAccess.item);
''','''"Remapped value", GH_ParamAccess.item);
            pManager.AddNumberParameter("Normalized", "N", "Position of the number in the source range (0-1)", GH_ParamAccess.item);
''')
s=s.replace('''            double value = 0, sMin = 0, sMax = 0, tMin = 0, tMax = 0;
''','''            double value = 0, sMin = 0, sMax = 0, tMin = 0, tMax = 0;
            bool clamp = false;
''')
s=s.replace('''            if (!DA.GetData(4, ref tMax)) return;
''','''            if (!DA.GetData(4, ref tMax)) return;
            DA.GetData(5, ref clamp);
''')
s=s.replace('''            DA.SetData(0, tMin + t * (tMax - tMin));''','''            var result = tMin + t * (tMax - tMin);
            if (clamp) result = Math.Max(Math.Min(tMin, tMax), Math.Min(Math.Max(tMin, tMax), result));
            DA.SetData(0, result);
            DA.SetData(1, t);''')
open(p,'w').write(s)
E
dotnet build 2>&1 | tail -5
